const FieldStatus = "status"

type Status = string

const StatusActive Status = "ACTIVE"
const StatusPending Status = "PENDING"
const StatusInactive Status = "INACTIVE"
const StatusSuspended Status = "SUSPENDED"
const StatusExpired Status = "EXPIRED"

func StatusValidator(v string) error {
	switch v {
	case "ACTIVE":
		return nil
	case "PENDING":
		return nil
	case "INACTIVE":
		return nil
	case "SUSPENDED":
		return nil
	case "EXPIRED":
		return nil
	}
	return fmt.Errorf("invalid Status: %s", v)
}
